from pathlib import Path

p=Path('src/intelligence/perceptionV6/index.js')
s=p.read_text()
s=s.replace('''  const contrast = surrounding.length ? distance(mean(samples), mean(surrounding)) : 0;\n  return { available: true, valid: true, reason: "pixels_sampled", crop: { x: x1, y: y1, width: x2-x1, height: y2-y1 }, sample_count: samples.length, surrounding_sample_count: surrounding.length, ratios, contrast, object_local_colors: localColors };''','''  const contrast = surrounding.length ? distance(mean(samples), mean(surrounding)) : 0;\n  const upperY2 = Math.min(y2, y1 + Math.max(1, Math.floor((y2 - y1) * .65)));\n  let upperEdgeComparisons = 0, upperStrongEdges = 0;\n  for (let y = y1; y < upperY2; y += stride) for (let x = x1; x + stride < x2; x += stride) {\n    const i=(y*image.width+x)*image.channels, j=(y*image.width+x+stride)*image.channels;\n    if (image.channels===4 && (image.data[i+3]<=15 || image.data[j+3]<=15)) continue;\n    const a=[image.data[i],image.data[i+1],image.data[i+2]], b=[image.data[j],image.data[j+1],image.data[j+2]];\n    if (pixelKind(a)==="skin" || pixelKind(b)==="skin") continue;\n    upperEdgeComparisons += 1;\n    if (distance(a,b) >= .055) upperStrongEdges += 1;\n  }\n  const spatial_structure={ upper_internal_edge_density: upperEdgeComparisons ? upperStrongEdges/upperEdgeComparisons : 0, upper_edge_comparisons: upperEdgeComparisons };\n  return { available: true, valid: true, reason: "pixels_sampled", crop: { x: x1, y: y1, width: x2-x1, height: y2-y1 }, sample_count: samples.length, surrounding_sample_count: surrounding.length, ratios, contrast, spatial_structure, object_local_colors: localColors };''',1)
s=s.replace('''  const isHeadwear = /hat|cap|beanie|headwear/.test(label);\n  const requiredEvidence = isHeadwear ? 3 : 2;\n  const structuralSignals = ["boundary_separation", "object_pixel_mass", "structured_dark_mass"];\n  const structuralEvidence = evidence.filter((item) => structuralSignals.includes(item));\n  const supported = evidence.length >= requiredEvidence && (!isHeadwear || structuralEvidence.length > 0);''','''  if (Number(pixels.spatial_structure?.upper_internal_edge_density || 0) >= .08) evidence.push("upper_internal_edge_structure");\n  const isHeadwear = /hat|cap|beanie|headwear/.test(label);\n  const requiredEvidence = isHeadwear ? 3 : 2;\n  const structuralSignals = ["upper_internal_edge_structure"];\n  const structuralEvidence = evidence.filter((item) => structuralSignals.includes(item));\n  const supported = evidence.length >= requiredEvidence && (!isHeadwear || structuralEvidence.length > 0);''',1)
p.write_text(s)
